content.css:
#newTableContainer {
  overflow: scroll;
  overflow-x: hidden;
  overflow-y: auto;
}
#newTable {
  border-collapse: collapse;
  z-index: -1;
}
#newTable th,
#newTable td {
  padding: 4px;
  padding-left: 8px;
  padding-right: 8px;
  border-left: 1px solid #c2c2c2;
  border-right: 1px solid #c2c2c2;
  font-weight: normal;
  font-family: "Arial", Helvetica, sans-serif;
  font-size: 8px;
}
#newTable th {
  color: white;
  padding-right: 16px;
}
#newTable td {
  background-color: white;
  color: #333;
  cursor: auto;
}
#newTable button {
  font-weight: normal;
  font-family: "Arial", Helvetica, sans-serif;
  font-size: 8px;
  text-align: left;
}
#unsortContainer {
  padding-left: 3px;
  padding-bottom: 5px;
  font-size: 11px;
  display: inline-block;
}
#fieldsContainer {
  padding-bottom: 5px;
  padding-left: 15px;
  font-size: 11px;
  display: inline-block;
}
#fieldsHeader {
  color: #555;
  font-weight: bold;
  font-family: "Arial", Helvetica, sans-serif;
  font-size: 16px;
  text-align: left;
  padding-bottom: 7px;
}
#modal {
  width: 70%;
  height: 60%;
  background-color: white;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);
  box-sizing: border-box;
  margin: 0 auto 0;
  border: 1px solid #d5d5d5;
  padding: 24px 30px 30px;
  -webkit-box-sizing: border-box;
  position: absolute;
  z-index: 7;
  font-weight: bold;
  font-family: "Arial", Helvetica, sans-serif;
  font-size: 12px;
  text-align: left;
}
#modal a {
  -webkit-appearance: none;
  -moz-appearance: none;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
  text-transform: uppercase;
  position: relative;
  outline: 0;
  cursor: pointer;
  text-align: center;
  display: inline-block;
  vertical-align: top;
  -webkit-transition: color 0.3s;
  transition: color 0.3s;
  font-size: 14px;
  font-weight: 700;
  padding: 10px 12px;
  letter-spacing: 0.5px;
  min-width: 90px;
  border-radius: 4px;
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
  margin-right: 20px;
  -webkit-font-smoothing: antialiased;
}
#buttonsContainer {
  padding-top: 10px;
}
#confirm {
  color: #fff;
  background: #555;
}
#cancel {
  color: #555;
  background: #DBDBDB;
}
#navigateContainer {
  padding-top: 8px;
  padding-right: 5px;
  float: right;
}
.downButton {
  padding-left: 5px;
}
.sortButton {
  display: inline-block;
  vertical-align: middle;
  padding-left: 5px;
}
.checkBoxTable {
  background-color: white;
  overflow: scroll;
  overflow-x: hidden;
  overflow-y: auto;
  width: 90%;
  height: 75%;
  border-top: 1px solid #d5d5d5;
}
.checkBoxTable tr {
  padding: 3px;
  border-bottom: 1px solid #d5d5d5;
  border-left: 1px solid #d5d5d5;
  border-right: 1px solid #d5d5d5;
  display: block;
}
input[type=checkbox] + label {
  display: inline-block;
  margin: 0.2em;
  cursor: pointer;
  padding: 0.2em;
}
input[type=checkbox] {
  display: none;
}
input[type=checkbox] + label:before {
  content: "\2714";
  border: 0.1em solid #000;
  border-radius: 0.2em;
  display: inline-block;
  width: 1em;
  height: 1em;
  padding-left: 0.2em;
  padding-bottom: 0.3em;
  margin-right: 0.2em;
  vertical-align: bottom;
  color: transparent;
}
input[type=checkbox] + label:active:before {
  transform: scale(0);
}
input[type=checkbox]:checked + label:before {
  background-color: #555;
  border-color: #555;
  color: #fff;
}


